<script setup lang="ts">const open=ref(false),{authenticated}=useAuth(),{items,load,markRead,unreadCount}=useNotifications();onMounted(()=>{if(authenticated.value)void load();});watch(authenticated,(value:boolean)=>{if(value)void load();});</script>
<template><div v-if="authenticated" class="notification-bell"><button class="icon-button" type="button" aria-label="اعلان‌ها" :aria-expanded="open" @click="open=!open">🔔<span v-if="unreadCount" class="notification-badge">{{unreadCount>99?'۹۹+':unreadCount}}</span></button><section v-if="open" class="notification-popover" aria-label="اعلان‌های تازه"><header><strong>اعلان‌ها</strong><NuxtLink to="/my/notifications" @click="open=false">مشاهده همه</NuxtLink></header><NotificationItem v-for="item in items.slice(0,3)" :key="item.id" :item="item" @read="markRead" @archive="()=>{}"/><p v-if="!items.length">اعلان تازه‌ای ندارید.</p></section></div></template>
